"""Fixed worked examples for the few-shot protocol: one disjoint training-split task per contract.

Shown identically to every arm (training, base, SFT and RL evaluation). They sit in the user prompt, so
their tokens are never part of a generated completion or its loss.
"""
import os

STRICT_TASK = 'level1/98_KLDivLoss'
HYBRID_TASK = 'level2/16_ConvTranspose2d_Mish_Add_Hardtanh_Scaling'

STRICT_REFERENCE = 'import torch\nimport torch.nn as nn\n\nclass Model(nn.Module):\n    """\n    A model that computes Kullback-Leibler Divergence for comparing two distributions.\n\n    Parameters:\n        None\n    """\n    def __init__(self):\n        super(Model, self).__init__()\n\n    def forward(self, predictions, targets):\n        return torch.nn.functional.kl_div(torch.log(predictions), targets, reduction=\'batchmean\')\n\nbatch_size = 8192 * 2\ninput_shape = (8192 * 2,)\ndim = 1\n\ndef get_inputs():\n    scale = torch.rand(())\n    return [(torch.rand(batch_size, *input_shape)*scale).softmax(dim=-1), torch.rand(batch_size, *input_shape).softmax(dim=-1)]\n\ndef get_init_inputs():\n    return []'

STRICT_SOLUTION = 'import torch\nimport torch.nn as nn\nimport triton\nimport triton.language as tl\n\n\n@triton.jit\ndef kl_partial_kernel(p_ptr, t_ptr, partial_ptr, n, iters, BLOCK: tl.constexpr):\n    pid = tl.program_id(0)\n    acc = tl.zeros((BLOCK,), dtype=tl.float32)\n    for it in range(iters):  # grid-stride loop: a fixed grid keeps the final reduction to one block\n        offs = (it * tl.num_programs(0) + pid) * BLOCK + tl.arange(0, BLOCK)\n        mask = offs < n\n        p = tl.load(p_ptr + offs, mask=mask, other=1.0)\n        t = tl.load(t_ptr + offs, mask=mask, other=0.0)\n        safe_t = tl.where(t > 0, t, 1.0)\n        acc += tl.where(t > 0, t * (tl.log(safe_t) - tl.log(p)), 0.0)\n    tl.store(partial_ptr + pid, tl.sum(acc, axis=0))\n\n\n@triton.jit\ndef finish_kernel(partial_ptr, out_ptr, m, batch, BLOCK: tl.constexpr):\n    offs = tl.arange(0, BLOCK)\n    total = tl.sum(tl.load(partial_ptr + offs, mask=offs < m, other=0.0), axis=0)\n    tl.store(out_ptr, total / batch)\n\n\nclass ModelNew(nn.Module):\n    def __init__(self):\n        super().__init__()\n\n    def forward(self, predictions, targets):\n        p = predictions.contiguous()\n        t = targets.contiguous()\n        n = p.numel()\n        programs, block = 1024, 1024\n        partial = torch.empty((programs,), device=p.device, dtype=torch.float32)\n        out = torch.empty((), device=p.device, dtype=p.dtype)\n        kl_partial_kernel[(programs,)](p, t, partial, n, triton.cdiv(n, programs * block), BLOCK=block)\n        finish_kernel[(1,)](partial, out, programs, p.shape[0], BLOCK=programs)\n        return out'

HYBRID_REFERENCE = 'import torch\nimport torch.nn as nn\n\nclass Model(nn.Module):\n    """\n    Model that performs a transposed convolution, applies Mish activation, adds a value, \n    applies Hardtanh activation, and scales the output.\n    """\n    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, add_value, scale):\n        super(Model, self).__init__()\n        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, stride, padding, output_padding)\n        self.add_value = add_value\n        self.scale = scale\n\n    def forward(self, x):\n        x = self.conv_transpose(x)\n        x = torch.nn.functional.mish(x) # Mish activation\n        x = x + self.add_value\n        x = torch.nn.functional.hardtanh(x, min_val=-1, max_val=1) # Hardtanh activation\n        x = x * self.scale # Scaling\n        return x\n\nbatch_size = 128\nin_channels  = 64  \nout_channels = 64  \nheight = width = 128  \nkernel_size  = 3\nstride       = 2  \npadding      = 1\noutput_padding = 1\nadd_value = 0.5\nscale = 2\n\ndef get_inputs():\n    return [torch.rand(batch_size, in_channels, height, width)]\n\ndef get_init_inputs():\n    return [in_channels, out_channels, kernel_size, stride, padding, output_padding, add_value, scale]'

HYBRID_SOLUTION = 'import torch\nimport torch.nn as nn\nimport torch.nn.functional as F\nimport triton\nimport triton.language as tl\n\n\n@triton.jit\ndef mish_add_hardtanh_scale_kernel(x_ptr, y_ptr, n, add_value, scale, BLOCK: tl.constexpr):\n    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)\n    mask = offs < n\n    x = tl.load(x_ptr + offs, mask=mask)\n    sp = tl.where(x > 20.0, x, tl.log(1.0 + tl.exp(x)))  # softplus, linear for large x\n    y = x * (1.0 - 2.0 / (tl.exp(2.0 * sp) + 1.0)) + add_value  # mish(x) = x * tanh(softplus(x))\n    y = tl.minimum(tl.maximum(y, -1.0), 1.0) * scale\n    tl.store(y_ptr + offs, y, mask=mask)\n\n\nclass ModelNew(nn.Module):\n    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, add_value, scale):\n        super().__init__()\n        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, stride, padding, output_padding)\n        self.add_value = add_value\n        self.scale = scale\n\n    def forward(self, x):\n        c = self.conv_transpose\n        # vendor library for the transposed convolution, in the reference dtype\n        y = F.conv_transpose2d(x, c.weight, c.bias, c.stride, c.padding, c.output_padding).contiguous()\n        out = torch.empty_like(y)\n        n = y.numel()\n        # one fused kernel replaces four elementwise passes over the large conv output\n        mish_add_hardtanh_scale_kernel[(triton.cdiv(n, 1024),)](y, out, n, self.add_value, self.scale, BLOCK=1024)\n        return out'

EXAMPLES = {1: (STRICT_TASK, STRICT_REFERENCE, STRICT_SOLUTION), 2: (HYBRID_TASK, HYBRID_REFERENCE, HYBRID_SOLUTION)}


def enabled():
    return os.environ.get('KERNEL_ENV_FEWSHOT', '0') == '1'


def block(level):
    task_id, reference, solution = EXAMPLES[1 if level == 1 else 2]
    return (f"\n\nWorked example from a different task ({task_id}), verified correct by this evaluator.\n"
            f"Reference:\n```python\n{reference}\n```\nA valid answer:\n```python\n{solution}\n```")
